import{_ as e,c as a,o as t,a4 as o}from"./chunks/framework.CRCV4hx_.js";const y=JSON.parse('{"title":"Core Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"core-concepts.md","filePath":"core-concepts.md"}'),i={name:"core-concepts.md"},r=o('<h1 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h1><p>Here you can find a basic outline of how Statamic Resrv works and how to better integrate it into your Statamic project.</p><h2 id="what-is-statamic-resrv" tabindex="-1">What is Statamic Resrv? <a class="header-anchor" href="#what-is-statamic-resrv" aria-label="Permalink to &quot;What is Statamic Resrv?&quot;">​</a></h2><p>Resrv is a content-agnostic reservation engine built using Laravel and &quot;living&quot; inside a Statamic CMS installation. It integrates with the power of Statamic to provide a powerful and flexible reservation system for any possible use.</p><h2 id="who-can-use-this" tabindex="-1">Who can use this? <a class="header-anchor" href="#who-can-use-this" aria-label="Permalink to &quot;Who can use this?&quot;">​</a></h2><p>Practically every business that needs reservations, like a hotel, a restaurant, a conference, car rental, boat rental, and more. Resrv is designed to be flexible and cater to many different business scenarios.</p><p>Besides the core functionality, it also has many extra functionalities that can be used to build your reservation system. That way, every business can have an in-house reservation system on their website and take reservations without paying huge reservation fees or expensive monthly subscriptions.</p><h2 id="how-does-it-work" tabindex="-1">How does it work? <a class="header-anchor" href="#how-does-it-work" aria-label="Permalink to &quot;How does it work?&quot;">​</a></h2><p>Statamic Resrv is built on top of Statamic&#39;s Entries. Every Entry in your site can be a &quot;product&quot; that can have availability, pricing, and more.</p><p>What&#39;s even cooler is that you can even sell completely different products. For example, you can have a Collection of hotel rooms to reserve and, in the very same Statamic installation, a Collection of cars for rent.</p><p>In the <strong>backend</strong>, using Statamic&#39;s control panel, you can access the reservation calendar in each Entry simply by adding a Resrv Availability field to your Collection.</p><p>A single Entry can also offer multiple <a href="./rates">Rates</a>: for example different room types or pricing tiers that share or own their own inventory. Rates are scoped per Collection, so you set them up once and reuse them across all the Entries in that Collection.</p><p>Also in the control panel, you can find a wealth of extra tools, like a list of all the Reservations, a Calendar, Reports, CSV Export, <a href="./rates">Rates</a>, <a href="./dynamic-pricing">Dynamic Pricing</a> (discounts &amp; coupons), an <a href="./affiliates">Affiliate</a> system, and more.</p><p>In the <strong>frontend</strong>, we provide a number of Laravel Livewire components that handle availability search, showing the results, the checkout process, and more.</p><h2 id="required-steps" tabindex="-1">Required steps <a class="header-anchor" href="#required-steps" aria-label="Permalink to &quot;Required steps&quot;">​</a></h2><p>Resrv can be quite complex to set up, depending on the use case. But here are the general steps that you need to follow to get started:</p><ol><li><a href="./installation">Install</a> the addon and migrate the database. Most settings now live in the control panel under <strong>Resrv → Settings</strong>, so the config file is optional and only needed for developer keys like payment gateways.</li><li>Create the <a href="./checkout">checkout page</a>, which contains the Checkout Livewire component and the checkout complete page.</li><li><a href="./configuration#checkout">Configure Resrv</a> to use the above pages.</li><li>Add a <a href="./availability">Resrv Availability</a> field to one of your Collections.</li><li>Add pricing and availability to your Entries.</li><li>If you need more than one rate per Entry (room types, pricing tiers, and so on), create your <a href="./rates">Rates</a> for the Collection.</li><li>Add any additional <a href="./extras">Extras</a> or <a href="./options">Options</a> that you may need.</li><li>Set up your <a href="./payment-gateways">payment gateways</a> and configure the webhooks. <a href="./stripe">Stripe</a> is supported out of the box, an offline / bank-transfer gateway is bundled, you can run multiple gateways at once, and <a href="./mollie">Mollie</a> is available as a separate add-on.</li><li>Add the <a href="./frontend-setup">frontend</a> assets and use the Livewire components to add availability search to your site.</li><li>Profit!</li></ol><div class="tip custom-block"><p class="custom-block-title">Upgrading from v5?</p><p>If you already run Resrv v5, follow the <a href="./upgrading">Upgrading to v6</a> guide. The old &quot;advanced availability&quot; and &quot;connected availabilities&quot; features have been replaced by the new <a href="./rates">Rates</a> system.</p></div>',18),n=[r];function s(l,c,h,d,p,u){return t(),a("div",null,n)}const m=e(i,[["render",s]]);export{y as __pageData,m as default};
